import { ActionDefinition } from '../../../Action'
import {
    TableNameColumn,
    ReferenceColumn,
    StringColumn,
    BooleanColumn,
    DocumentIdColumn,
    ChoiceColumn,
} from '../../../../db'

export const recordProducer = ActionDefinition({
    $id: '87a397837333001098e194596bf6a7bc',
    name: 'Record Producer',
    description: 'Creates a record on a table in the system.',
    category: 'bf2f2fec73f70300b61e66476bf6a774',
    inputs: {
        record_table: TableNameColumn({
            label: 'Record Table',
            attributes: {
                visible_in_fd: 'false',
            },
        }),
        catalog_item: ReferenceColumn({
            label: 'Catalog Item',
            mandatory: true,
            referenceTable: 'sc_cat_item',
        }),
        catalog_item_inputs: StringColumn({
            label: 'Catalog Item Inputs',
            maxLength: 32000000,
        }),
        _snc_dont_fail_on_error: BooleanColumn({
            label: "Don't fail on error",
        }),
    },
    outputs: {
        error_message: StringColumn({
            label: 'Error Message',
            maxLength: 8000,
        }),
        record: DocumentIdColumn({
            dependent: 'record_table',
            label: 'Record',
        }),
        table: TableNameColumn({
            label: 'Table',
        }),
        status: ChoiceColumn({
            label: 'Status',
            maxLength: 32,
            default: '0',
            choices: {
                0: {
                    label: 'Success',
                },
                1: {
                    label: 'Error',
                    sequence: 1,
                },
            },
        }),
    },
})
